// The ad-hoc request protocol: the labels a person uses to hand this repo's own
// executor a one-off piece of work, and who is allowed to. Pure data and pure
// functions — no I/O — so the three tasks' preconditions, their prework and the
// tests all read one definition of what an eligible request is.
//
// THE LABEL IS THE WHOLE REQUEST. There is no request file, no body syntax and
// nothing to keep in sync: an issue wearing `claude-task` is a request, and its
// optional `claude-model:<family>` says at which model. That is deliberate —
// the mark has to be something a person can apply from the issue page on a
// phone, and anything richer would be a form nobody fills in twice.
//
// AND THE LABEL IS CONSUMED. Prework swaps `claude-task` for `claude-running`
// when it hands an issue to the agent, so the condition the precondition gates
// on clears itself by being acted on. A request that fails leaves `claude-running`
// standing and is NOT retried: re-applying `claude-task` is a person's decision,
// which is the right default for work that writes code.

// The mark: "let Claude do this task".
export const REQUEST_LABEL = 'claude-task';
// In flight — prework moved the request here and named it to an agent.
export const RUNNING_LABEL = 'claude-running';
// Done — the agent finished and left a pull request behind.
export const DONE_LABEL = 'claude-done';
// The optional model choice, `claude-model:<family>`.
export const MODEL_LABEL_PREFIX = 'claude-model:';

// The families a request may name, in the order a request wearing more than one
// model label is resolved. Not imported from the engine's MODEL_FAMILIES on
// purpose: that list carries `none`, which is agentless and cannot implement
// anything, and this pack ships exactly one task per family below.
export const FAMILIES = ['opus', 'sonnet', 'haiku'];
export const DEFAULT_FAMILY = 'opus';

// The label set, ensured before any of them is applied — GitHub 422s on applying
// a label that does not exist, so whatever assigns one must guarantee it first.
export const REQUEST_LABELS = [
  { name: REQUEST_LABEL, color: '5319e7', description: 'Claudinite: implement this issue on the next executor run' },
  { name: RUNNING_LABEL, color: 'fbca04', description: 'Claudinite: an agent session is implementing this issue' },
  { name: DONE_LABEL, color: '0e8a16', description: 'Claudinite: an agent implemented this issue and left a pull request' },
  ...FAMILIES.map((f) => ({
    name: `${MODEL_LABEL_PREFIX}${f}`,
    color: 'c5def5',
    description: `Claudinite: run this request at the ${f} model family`,
  })),
];

// Which family a set of labels asks for — or null when these labels are not a
// request at all. An unrecognized `claude-model:` value resolves to the default
// rather than to nothing: a request nobody can pick up would sit on the issue
// looking accepted forever, and the model a run actually used is stated on the
// issue when it is picked up, so the fallback is visible rather than silent.
export function modelFor(labels) {
  const names = (labels ?? []).map((l) => (typeof l === 'string' ? l : l?.name)).filter(Boolean);
  if (!names.includes(REQUEST_LABEL)) return null;
  const asked = names.filter((n) => n.startsWith(MODEL_LABEL_PREFIX)).map((n) => n.slice(MODEL_LABEL_PREFIX.length));
  return FAMILIES.find((f) => asked.includes(f)) ?? DEFAULT_FAMILY;
}

// The open requests for one family, oldest first. Issue number ascending IS
// oldest-first and is stable under any later edit, which `updated_at` is not.
export function requestsFor(issues, family) {
  return (issues ?? [])
    .filter((i) => modelFor(i.labels) === family)
    .map((i) => i.number)
    .sort((a, b) => a - b);
}

// WHO MAY ASK. `author_association` is computed by GitHub from the asker's
// permission on the repository and travels on every issue and comment payload,
// so it cannot be forged by anyone who can type — which is what makes this the
// whole of the check. These three are the associations that carry write access.
export const PUSH_ASSOCIATIONS = ['OWNER', 'MEMBER', 'COLLABORATOR'];
export const hasPushAccess = (association) => PUSH_ASSOCIATIONS.includes(association);

// The approval phrase, for an issue somebody else opened: a collaborator's
// comment blesses it. Anchored to the start of a line so quoting the phrase
// while discussing it does not approve anything.
export const APPROVAL_RE = /^\s*\/claude\s+go\b/im;

// Is this request eligible to run? `issue` and `comments` are raw GitHub
// payloads. Returns { ok, why } — `why` is the sentence the run reports either
// way, so the refusal that lands on the issue and the approval that lands on the
// work item come from the same place.
export function eligibility(issue, comments = []) {
  if (hasPushAccess(issue?.author_association)) {
    return { ok: true, why: `opened by @${issue?.user?.login}, who has write access to this repo` };
  }
  const approval = (comments ?? []).find((c) => hasPushAccess(c?.author_association) && APPROVAL_RE.test(c?.body ?? ''));
  if (approval) return { ok: true, why: `approved by @${approval.user?.login} with \`/claude go\`` };
  return {
    ok: false,
    why: `neither opened by someone with write access nor approved by one — a collaborator must comment \`/claude go\` on it`,
  };
}
