write_task sonnet 'the choice for a request whose shape is already decided — a mechanical change, a rename, a well-specified fix — where the deciding is done and the work is application.' 5400
write_task haiku 'the choice for a request that is nearly clerical — a one-line edit, a doc typo — where the whole ask fits in its title.' 3600
node --check tasks/implement-opus/task.mjs && node -e "import('./tasks/implement-opus/task.mjs').then(m=>{const d=m.default;console.log(d.id,d.agent_model);console.log(JSON.stringify(d.precondition({issues:{open:[{number:7,labels:[{name:'claude-task'}]},{number:9,labels:['claude-task','claude-model:haiku']}]}}),null,1));console.log(JSON.stringify(d.precondition({issues:{open:[]}})))})"

