import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readdirSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import pack from '../../packs/claudinite-tasks-adhoc/pack.mjs';
import {
  REQUEST_LABEL, RUNNING_LABEL, FAMILIES, DEFAULT_FAMILY,
  modelFor, requestsFor, eligibility,
} from '../../packs/claudinite-tasks-adhoc/request.mjs';
import { pickRequest } from '../../packs/claudinite-tasks-adhoc/pick.mjs';
import { validateTaskDeclaration } from '../../engine/scheduler/task-contract.mjs';

const PACK_DIR = join(dirname(fileURLToPath(import.meta.url)), '../../packs/claudinite-tasks-adhoc');

const labelled = (number, ...names) => ({ number, labels: names.map((name) => ({ name })) });

test('the pack ships one task per model family, each declaring that family', async () => {
  assert.equal(pack.id, 'claudinite-tasks-adhoc');
  assert.equal(pack.detect, null);                       // opt-in: never fingerprinted into a repo
  assert.equal(pack.seededByDefault, false);
  assert.deepEqual(
    readdirSync(join(PACK_DIR, 'tasks')).sort(),
    FAMILIES.map((f) => `implement-${f}`).sort(),
  );

  for (const family of FAMILIES) {
    const dir = join(PACK_DIR, 'tasks', `implement-${family}`);
    const decl = (await import(join(dir, 'task.mjs'))).default;
    assert.deepEqual(validateTaskDeclaration(decl), [], `implement-${family} is a valid declaration`);
    assert.equal(decl.id, `implement-${family}`);
    assert.equal(decl.expected_outcome, 'open-pr');       // the ceiling: it may open, never merge
    assert.ok(existsSync(join(dir, decl.agent_instructions)));

    // THE DRIFT GUARD between the two halves of one file: the model the executor
    // dispatches at (`agent_model`) and the family the precondition claims
    // requests for. They are separate literals because the declaration must stay
    // statically readable, and a run at the wrong model would look entirely
    // healthy — the request would be picked up, just not by the task the label
    // asked for.
    const seesOwnFamily = decl.precondition({ issues: { open: [labelled(1, REQUEST_LABEL, `claude-model:${family}`)] } });
    assert.equal(seesOwnFamily.run, true, `implement-${family} claims its own family's requests`);
    for (const other of FAMILIES.filter((f) => f !== family)) {
      const verdict = decl.precondition({ issues: { open: [labelled(1, REQUEST_LABEL, `claude-model:${other}`)] } });
      assert.equal(verdict.run, false, `implement-${family} (agent_model ${decl.agent_model}) leaves ${other} requests alone`);
    }
  }
});

test('the default family claims an unlabelled request, and every family claims exactly one', () => {
  assert.equal(modelFor([REQUEST_LABEL]), DEFAULT_FAMILY);
  assert.equal(modelFor([{ name: REQUEST_LABEL }, { name: 'claude-model:haiku' }]), 'haiku');
  // An unrecognized family resolves to the default rather than to nothing: a
  // request nobody can pick up would sit on the issue looking accepted forever.
  assert.equal(modelFor([REQUEST_LABEL, 'claude-model:sonnett']), DEFAULT_FAMILY);
  assert.equal(modelFor(['bug', 'claude-model:opus']), null);   // no request label is no request
  assert.equal(modelFor([]), null);
});

test('requests come back oldest first, by issue number', () => {
  const open = [labelled(9, REQUEST_LABEL), labelled(2, REQUEST_LABEL), labelled(5, 'bug')];
  assert.deepEqual(requestsFor(open, DEFAULT_FAMILY), [2, 9]);
});

test('eligibility takes write access from the asker, and an approval from a comment', () => {
  const outsider = { number: 1, user: { login: 'someone' }, author_association: 'NONE' };
  assert.equal(eligibility({ ...outsider, author_association: 'OWNER' }).ok, true);
  assert.equal(eligibility({ ...outsider, author_association: 'COLLABORATOR' }).ok, true);
  assert.equal(eligibility(outsider).ok, false);
  assert.equal(eligibility(outsider, [{ author_association: 'OWNER', body: '/claude go', user: { login: 'o' } }]).ok, true);
  // The phrase only counts from someone who could have applied the label anyway…
  assert.equal(eligibility(outsider, [{ author_association: 'NONE', body: '/claude go', user: { login: 'x' } }]).ok, false);
  // …and only when it is the line, not a quotation of it.
  assert.equal(eligibility(outsider, [{ author_association: 'OWNER', body: '> /claude go\n\nnot yet', user: { login: 'o' } }]).ok, false);
});

// A `gh` double: canned issue list + comments, every write recorded.
function fakeGh({ issues, comments = {} }) {
  const calls = [];
  const gh = async (path, opts = {}) => {
    calls.push({ path, method: opts.method ?? 'GET', body: opts.body });
    if (opts.method === undefined && path.includes('/issues?labels=')) return { status: 200, json: issues };
    if (opts.method === undefined && /\/issues\/\d+\/comments/.test(path)) {
      return { status: 200, json: comments[Number(/issues\/(\d+)/.exec(path)[1])] ?? [] };
    }
    return { status: 201, json: {} };
  };
  return { gh, calls };
}
const wrote = (calls, method, re) => calls.filter((c) => c.method === method && re.test(c.path));

test('prework picks the oldest eligible request, and takes its request label off it', async () => {
  const { gh, calls } = fakeGh({
    issues: [
      { ...labelled(12, REQUEST_LABEL), title: 'later', author_association: 'OWNER', user: { login: 'o' } },
      { ...labelled(4, REQUEST_LABEL), title: 'earlier', author_association: 'OWNER', user: { login: 'o' } },
    ],
  });
  const { chosen, refused } = await pickRequest({ gh, repo: 'o/r', family: DEFAULT_FAMILY, item: 77 });

  assert.equal(chosen.number, 4);
  assert.deepEqual(refused, []);
  assert.equal(wrote(calls, 'DELETE', new RegExp(`/issues/4/labels/${REQUEST_LABEL}`)).length, 1);
  assert.deepEqual(wrote(calls, 'POST', /\/issues\/4\/labels/)[0].body, { labels: [RUNNING_LABEL] });
  // The issue that did not win this run is left exactly as it was.
  assert.deepEqual(calls.filter((c) => c.method !== 'GET' && /\/issues\/12\b/.test(c.path)), []);
  assert.match(wrote(calls, 'POST', /\/issues\/4\/comments/)[0].body.body, /opus/);
});

test('an unauthorized request is refused once and disarmed, never left to re-fire', async () => {
  const { gh, calls } = fakeGh({
    issues: [{ ...labelled(3, REQUEST_LABEL), title: 'drive-by', author_association: 'NONE', user: { login: 'x' } }],
    comments: { 3: [{ author_association: 'NONE', body: '/claude go', user: { login: 'x' } }] },
  });
  const { chosen, refused } = await pickRequest({ gh, repo: 'o/r', family: DEFAULT_FAMILY });

  assert.equal(chosen, null);                              // a legal empty outcome, not a skip
  assert.deepEqual(refused.map((r) => r.number), [3]);
  assert.match(wrote(calls, 'POST', /\/issues\/3\/comments/)[0].body.body, /Not implementing this/);
  assert.equal(wrote(calls, 'DELETE', new RegExp(`/issues/3/labels/${REQUEST_LABEL}`)).length, 1);
  assert.deepEqual(wrote(calls, 'POST', new RegExp(`/issues/3/labels$`)), []);   // and never marked running
});

test('an unauthorized request ahead of an eligible one blocks nothing', async () => {
  const { gh } = fakeGh({
    issues: [
      { ...labelled(1, REQUEST_LABEL), title: 'drive-by', author_association: 'NONE', user: { login: 'x' } },
      { ...labelled(6, REQUEST_LABEL), title: 'real', author_association: 'MEMBER', user: { login: 'm' } },
    ],
  });
  const { chosen, refused } = await pickRequest({ gh, repo: 'o/r', family: DEFAULT_FAMILY });
  assert.equal(chosen.number, 6);
  assert.deepEqual(refused.map((r) => r.number), [1]);
});

test('no requests at all touches nothing — not even the label set', async () => {
  const { gh, calls } = fakeGh({ issues: [] });
  const { chosen } = await pickRequest({ gh, repo: 'o/r', family: 'haiku' });
  assert.equal(chosen, null);
  assert.deepEqual(calls.filter((c) => c.method !== 'GET'), []);
});
EOF
