    req.labels.delete(QUEUED_LABEL);
    req.labels.add(IN_REVIEW_LABEL);
    record('request-in-review', { issue: req.number, item: it.number });
  }

  // ---- the executor (DESIGN §6) ---------------------------------------------""")

